{
    "name": "@zeklop/opencode-antigravity-auth",
    "version": "1.6.4",
    "description": "OpenCode OAuth plugin for Antigravity and Gemini models",
    "main": "./dist/index.js",
    "types": "./dist/index.d.ts",
    "type": "module",
    "license": "MIT",
    "author": "noefabris",
    "publishConfig": {
        "access": "public"
    },
    "bin": {
        "gquota": "dist/src/quota-cli.js"
    },
    "repository": {
        "type": "git",
        "url": "git+https://github.com/zeklop/opencode-antigravity-auth.git"
    },
    "homepage": "https://github.com/zeklop/opencode-antigravity-auth#readme",
    "bugs": {
        "url": "https://github.com/zeklop/opencode-antigravity-auth/issues"
    },
    "keywords": [
        "opencode",
        "google",
        "antigravity",
        "gemini",
        "oauth",
        "plugin",
        "auth",
        "claude"
    ],
    "engines": {
        "node": ">=20.0.0"
    },
    "files": [
        "dist/",
        "README.md",
        "LICENSE"
    ],
    "scripts": {
        "build": "tsc -p tsconfig.build.json && node script/fix-esm-imports.mjs",
        "build:schema": "npx tsx script/build-schema.ts",
        "typecheck": "tsc --noEmit",
        "test": "vitest run",
        "test:watch": "vitest",
        "test:ui": "vitest --ui",
        "test:coverage": "vitest run --coverage",
        "prepublishOnly": "npm run build",
        "test:e2e:models": "npx tsx script/test-models.ts",
        "test:e2e:regression": "npx tsx script/test-regression.ts"
    },
    "peerDependencies": {
        "typescript": "^5"
    },
    "devDependencies": {
        "@types/node": "^24.10.1",
        "@types/proper-lockfile": "^4.1.4",
        "@vitest/coverage-v8": "^3.0.0",
        "@vitest/ui": "^3.0.0",
        "typescript": "^5.0.0",
        "vitest": "^3.0.0",
        "zod-to-json-schema": "^3.25.1"
    },
    "dependencies": {
        "@opencode-ai/plugin": "^0.15.30",
        "@openauthjs/openauth": "^0.4.3",
        "proper-lockfile": "^4.1.2",
        "xdg-basedir": "^5.1.0",
        "zod": "^4.0.0"
    }
}
